        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeUploadProgress.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface UploadProgress: handle missing in uniffiClone")
            }
        },
